private static void readMultiplePolygons(String line, HashMap<String, List<Polygon>> mapping) throws IOException {
    try {
        String name = line.substring(0, line.indexOf('<')).trim();
        int index = name.length();
        List<Polygon> polygons = new ArrayList<Polygon>(64);
        ArrayList<Point> points = new ArrayList<Point>();
        final int length = line.length();
        while (index < length) {
            char current = line.charAt(index);
            if (current == '<') {
                int x = 0;
                int y = 0;
                int base = 0;
                while (true) {
                    current = line.charAt(++index);
                    switch (current) {
                        case '0': case '1': case '2': case '3': case '4': case '5': case '6': case '7': case '8': case '9':
                            base *= 10;
                            base += current - '0';
                            break;
                        case ',':
                            x = base;
                            base = 0;
                            break;
                        case ')':
                            y = base;
                            base = 0;
                            points.add(new Point(x, y));
                            break;
                        default:
                            break;
                    }
                    if (current == '>') {
                        createPolygonFromPoints(polygons, points);
                        points.clear();
                        break;
                    }
                }
            }
            index++;
        }
        if (mapping.containsKey(name)) throw new IOException("name found twice:" + name);
        mapping.put(name, polygons);
    } catch (RuntimeException e) {
        throw new RuntimeException("Error processing line: " + line, e);
    }
}
